/**
 * Read access to src/data/publications.json, which is generated by
 * scripts/fetch-publications.mjs. Never edit the JSON by hand: corrections go
 * in src/data/publications-extra.yml and wrong works in publications-ignore.yml.
 */
import data from '../data/publications.json';

export interface Author {
	name: string;
	me?: boolean;
}

export type Category = 'article' | 'conference' | 'preprint' | 'abstract' | 'dataset' | 'thesis';

export interface Work {
	title: string;
	authors: Author[];
	/** Cristobal's place in the author list, counting from 1. */
	position: number;
	year: number;
	date: string | null;
	venue: string | null;
	doi: string | null;
	/** Datasets only: every DOI seen for the record, so a page can cite any of them. */
	altDois?: string[];
	url: string;
	category: Category;
	openAccess: boolean;
	license: string | null;
}

export const WORKS = data as Work[];

/** Headings for each category, in the order the publications page lists them. */
export const CATEGORY_LABELS: Record<Exclude<Category, 'dataset'>, string> = {
	article: 'Journal articles',
	conference: 'Conference papers and book chapters',
	preprint: 'Preprints',
	abstract: 'Conference abstracts',
	thesis: 'Thesis',
};

export function byCategory(category: Category): Work[] {
	return WORKS.filter((w) => w.category === category);
}

export function byDoi(doi: string): Work | undefined {
	const wanted = doi.toLowerCase();
	return WORKS.find((w) => w.doi === wanted || w.altDois?.includes(wanted));
}

/**
 * Journal articles with Cristobal as first author. The two Frontiers for Young
 * Minds pieces are left out here, because they belong under engagement; they
 * still appear in the full list.
 */
export function firstAuthoredArticles(): Work[] {
	return byCategory('article').filter((w) => w.position === 1 && w.venue !== 'Frontiers for Young Minds');
}

/**
 * Shorten a long author list without hiding Cristobal's place in it: the first
 * three names, his own, and the last (usually the senior author), with gaps
 * marked. Short lists are printed whole.
 */
export function shortAuthors(authors: Author[], limit = 8): (Author | 'gap')[] {
	if (authors.length <= limit) return authors;
	const keep = new Set([0, 1, 2, authors.length - 1]);
	const mine = authors.findIndex((a) => a.me);
	if (mine >= 0) keep.add(mine);
	const out: (Author | 'gap')[] = [];
	let previous = -1;
	for (const index of [...keep].sort((a, b) => a - b)) {
		if (index - previous > 1) out.push('gap');
		out.push(authors[index]);
		previous = index;
	}
	return out;
}
